const events = $input.all().map(i => i.json);

const total = events.length;
const recovered = events.filter(e => e.status === 'recovered');
const pending = events.filter(e => e.status === 'pending');
const exhausted = events.filter(e => e.status === 'exhausted');
const noAction = events.filter(e => e.status === 'no_action_needed');

const totalAmount = events.reduce((s, e) => s + (Number(e.amount) || 0), 0);
const recoveredAmount = recovered.reduce((s, e) => s + (Number(e.recovered_amount) || Number(e.amount) || 0), 0);
const pendingAmount = pending.reduce((s, e) => s + (Number(e.amount) || 0), 0);

const recoveryRate = total > 0 ? (recovered.length / total * 100).toFixed(1) : 0;

// BASELINE COMPARISON: Industry avg recovery rate without AI is 15-20% (simple retries)
// Source: Razorpay blog - 15-20% of failed transactions recovered via simple retries
const INDUSTRY_BASELINE_RATE = 17.5; // midpoint of 15-20%
const aiRecoveryRate = Number(recoveryRate);
const aiLift = aiRecoveryRate > 0 ? Number((aiRecoveryRate - INDUSTRY_BASELINE_RATE).toFixed(1)) : 0;
const aiLiftMultiplier = INDUSTRY_BASELINE_RATE > 0 ? Number((aiRecoveryRate / INDUSTRY_BASELINE_RATE).toFixed(2)) : 0;

// Revenue impact: how much MORE was recovered vs baseline
const actionableEvents = events.filter(e => e.status !== 'no_action_needed');
const actionableAmount = actionableEvents.reduce((s, e) => s + (Number(e.amount) || 0), 0);
const baselineRecovery = actionableAmount * (INDUSTRY_BASELINE_RATE / 100);
const additionalRevenue = Math.max(0, recoveredAmount - baselineRecovery);

// Time metrics
const recoveredWithTime = recovered.filter(e => e.created_at && e.recovered_at);
const avgRecoveryTimeHours = recoveredWithTime.length > 0
  ? Number((recoveredWithTime.reduce((s, e) => {
      const created = new Date(e.created_at).getTime();
      const rec = new Date(e.recovered_at).getTime();
      return s + (rec - created) / 3600000;
    }, 0) / recoveredWithTime.length).toFixed(1))
  : null;

const byType = {};
for (const e of events) {
  const t = e.event_type || 'unknown';
  if (!byType[t]) byType[t] = { total: 0, recovered: 0, amount: 0, recovered_amount: 0, recovery_rate: 0 };
  byType[t].total++;
  byType[t].amount += Number(e.amount) || 0;
  if (e.status === 'recovered') {
    byType[t].recovered++;
    byType[t].recovered_amount += Number(e.recovered_amount) || Number(e.amount) || 0;
  }
  byType[t].recovery_rate = Number((byType[t].recovered / byType[t].total * 100).toFixed(1));
}

const byChannel = {};
for (const e of events) {
  const c = e.recommended_channel || 'none';
  if (!byChannel[c]) byChannel[c] = { total: 0, recovered: 0, amount: 0, recovery_rate: 0 };
  byChannel[c].total++;
  byChannel[c].amount += Number(e.amount) || 0;
  if (e.status === 'recovered') byChannel[c].recovered++;
  byChannel[c].recovery_rate = Number((byChannel[c].recovered / byChannel[c].total * 100).toFixed(1));
}

const byCategory = {};
for (const e of events) {
  const c = e.failure_category || 'unknown';
  if (!byCategory[c]) byCategory[c] = { total: 0, recovered: 0, avg_probability: 0, probSum: 0, recovery_rate: 0 };
  byCategory[c].total++;
  byCategory[c].probSum += Number(e.recovery_probability) || 0;
  byCategory[c].avg_probability = Number((byCategory[c].probSum / byCategory[c].total).toFixed(2));
  if (e.status === 'recovered') byCategory[c].recovered++;
  byCategory[c].recovery_rate = Number((byCategory[c].recovered / byCategory[c].total * 100).toFixed(1));
}
for (const k in byCategory) delete byCategory[k].probSum;

const recoveredWithAttempts = recovered.filter(e => e.attempt_count > 0);
const avgAttemptsToRecover = recoveredWithAttempts.length > 0
  ? Number((recoveredWithAttempts.reduce((s, e) => s + e.attempt_count, 0) / recoveredWithAttempts.length).toFixed(1))
  : 0;

// Channel effectiveness ranking
const channelRanking = Object.entries(byChannel)
  .filter(([k]) => k !== 'none')
  .sort((a, b) => b[1].recovery_rate - a[1].recovery_rate)
  .map(([k, v]) => ({ channel: k, ...v }));

return [{
  json: {
    summary: {
      total_events: total,
      recovered_count: recovered.length,
      pending_count: pending.length,
      exhausted_count: exhausted.length,
      no_action_count: noAction.length,
      recovery_rate_percent: Number(recoveryRate),
      total_amount: totalAmount,
      recovered_amount: recoveredAmount,
      pending_amount: pendingAmount,
      avg_attempts_to_recover: avgAttemptsToRecover,
      avg_recovery_time_hours: avgRecoveryTimeHours
    },
    ai_lift: {
      baseline_rate_percent: INDUSTRY_BASELINE_RATE,
      ai_recovery_rate_percent: aiRecoveryRate,
      improvement_points: aiLift,
      lift_multiplier: aiLiftMultiplier,
      additional_revenue_recovered: Number(additionalRevenue.toFixed(2)),
      baseline_source: 'Razorpay blog: 15-20% recovery via simple retries'
    },
    by_event_type: byType,
    by_channel: byChannel,
    channel_ranking: channelRanking,
    by_failure_category: byCategory,
    generated_at: new Date().toISOString()
  }
}];
